CREATE FUNCTION population_top3000_202608_202609_v1.ref01_practical_population_worker_v2(p_attempt uuid,p_token text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $f$
DECLARE tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;m jsonb;acc text;h text;v jsonb;z record;n integer:=0;k text;out_hash text;nextid uuid;calendar_hash text;contract_hash text;index_hash text;rules jsonb:='{"REF01": "Frozen selected companies joined to all eligible common/ADR/ADS listing episodes overlapping 2026-08-01 through 2026-09-30; reconcile new classes, aliases and weekend effective changes. Anchor points do not prove intervals.", "P01": "Verified listing-day crossed with official regular-session scheduled minutes; eligible-trade/no-trade evidence separate from minute opportunities.", "P02": "Verified listing-day crossed with independently specified extended-session boundaries and eligible-trade minutes; never infer no-trade from missing bars.", "D01": "Exact scheduled minute and 18 frozen nonresearch component definitions with required pre-window support; selective microstructure only where genuinely captured.", "D02": "Eligible listing-session crossed with declared daily fields and close convention; no stale close substitution.", "D03": "D02 eligible sessions crossed with raw and adjusted 1/5/20/60-session return definitions plus exact support history.", "D04": "D02/D03 eligible sessions crossed with frozen volatility, relative-volume and z-score definitions and complete lookbacks.", "D05": "Eligible security-session daily Amihud and 20-session rolling definition; zero denominator explicit.", "N01": "Complete source article/version index including weekends joined to dated issuer/security links and licensed components.", "N02": "Complete issuer/security action-event index crossed with independent date-role and vintage, including announced/effective dividends.", "N03": "Complete executed mechanical action index and effective share-unit intervals including required warmup adjustments.", "S01": "Complete FINRA daily file by reporting facility/session joined to dated security membership; published absence distinct from missing files.", "S02": "Settlement calendar crossed with applicable dated securities, reporting versions and required prior state; publication windows separate.", "F01": "Complete filing index joined to selected issuer roles/accessions/documents/exhibits/versions plus earlier supporting filings; index associations alone do not establish document population.", "F02": "Applicable F01 documents crossed with 39 mapping entries and 44 derived definitions by taxonomy/context/unit/period/vintage.", "F03": "Applicable reporting documents crossed with 32 requested metrics and dated company states including needed comparative history.", "F04": "Complete earnings-disclosure event index with earliest supported public release timestamps and versions.", "F05": "F04 events crossed with actuals, guidance and genuinely pre-announcement consensus vintages aligned by basis/period/currency before surprise calculation.", "F06": "Verified shares, float and capitalization effective intervals; approximate selection proxy is never a verified financial value.", "CTX02": "Full-window historical lifecycle contracts across selected underlying episodes crossed with applicable trading days; introduced/expired/adjusted contracts and no-trade evidence separate.", "CTX06": "Declared breadth evaluation times crossed with one vote per selected company; valid/missing instrument and D03 input denominators explicit.", "CTX07": "Exact 21 frozen series official release/revision calendar and required prior states, stored once without company multiplier.", "CTX14": "Exact eight roots crossed with relevant contract lives, futures calendars/minutes, settlements and roll definitions, without company multiplier.", "REF03": "Release dependency graph covering source/transform/expected-population/validation/exception/reader assertions; root-only acceptance and serving promotion."}'::jsonb;
BEGIN
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 PERFORM population_top3000_202608_202609_v1.ref01_practical_guard_v1();
 SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid;
 k:=t.payload->>'kind';h:=t.input_versions->>'cohort_sha256';
 IF t.family_id IS DISTINCT FROM 'REF01' OR k NOT IN('PRACTICAL_INTERVAL_REQUIREMENTS_V2','PRACTICAL_FAMILY_SPECS_V2','PRACTICAL_FILING_EXPECTATIONS_V2') OR k IS NULL THEN RAISE EXCEPTION 'POPULATION_KIND_REQUIRED';END IF;
 SELECT content INTO STRICT m FROM population_top3000_202608_202609_v1.ref01_practical_snapshot_v1 WHERE snapshot_sha256=h;
 SELECT acceptance_sha256 INTO STRICT acc FROM population_top3000_202608_202609_v1.ref01_practical_membership_v1 WHERE snapshot_sha256=h AND acceptance_sha256=encode(sha256(convert_to(content::text,'UTF8')),'hex');
 IF h IS DISTINCT FROM '2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' OR encode(sha256(convert_to(m::text,'UTF8')),'hex') IS DISTINCT FROM h
 OR t.input_versions->>'policy_sha256' IS DISTINCT FROM m->>'policy_sha256' OR t.input_versions->>'membership_acceptance_sha256' IS DISTINCT FROM acc OR t.input_versions->>'source_sha256' IS DISTINCT FROM m->>'source_sha256' THEN RAISE EXCEPTION 'POPULATION_FROZEN_INPUT_MISMATCH';END IF;
 SELECT encode(sha256(convert_to(string_agg(session_date::text||':'||source_record_sha256,E'\n' ORDER BY session_date),'UTF8')),'hex') INTO calendar_hash FROM population_top3000_202608_202609_v1.catalog_calendar;
 IF calendar_hash IS DISTINCT FROM t.input_versions->>'calendar_sha256' OR calendar_hash IS DISTINCT FROM 'cb97feec5b3ac3ae136b1bc7085ed842f2aaca5b6c98f97c0cb1c1dae8f336a1' THEN RAISE EXCEPTION 'POPULATION_CALENDAR_CHANGED';END IF;
 SELECT encode(sha256(convert_to(string_agg(family_id||':'||contract_sha256,E'\n' ORDER BY family_id COLLATE "C"),'UTF8')),'hex') INTO contract_hash FROM population_top3000_202608_202609_v1.catalog_family_contract;
 IF contract_hash IS DISTINCT FROM t.input_versions->>'family_contract_sha256' OR contract_hash IS DISTINCT FROM 'e47a1e4152768418bd8e6187310b34cfc7b096edbc1e1de11fe243275e046dc0' THEN RAISE EXCEPTION 'POPULATION_CONTRACT_CHANGED';END IF;
 IF k='PRACTICAL_FILING_EXPECTATIONS_V2' THEN
 WITH chosen AS MATERIALIZED(SELECT value->>'company_id' company_id FROM jsonb_array_elements(m->'companies')), r AS(SELECT i.source_id,i.source_line_number,c.company_id,i.accession_number,i.form,i.filing_date,i.source_filename FROM population_top3000_202608_202609_v1.sec_filing_index_v1 i JOIN chosen c ON c.company_id='CIK:'||lpad(i.filing_cik,10,'0') WHERE i.source_id='SEC_Q3_2026_MASTER_INDEX' AND i.filing_date BETWEEN '2026-08-01' AND '2026-09-30') SELECT encode(sha256(convert_to(string_agg(to_jsonb(r)::text,E'\n' ORDER BY source_id COLLATE "C",source_line_number),'UTF8')),'hex') INTO index_hash FROM r;
 IF index_hash IS DISTINCT FROM t.input_versions->>'filing_index_sha256' OR index_hash IS DISTINCT FROM '5605c4be0784a72b23371b7e5083e0421fcf5ecd3b08d9e416d4a7a434e5c35e' THEN RAISE EXCEPTION 'POPULATION_FILING_INDEX_CHANGED';END IF;
 END IF;
 IF t.stage='VALIDATE' THEN RETURN jsonb_build_object('state','BLOCKED','blocker_code','PRACTICAL_POPULATION_EVIDENCE_AND_INDEPENDENT_ACCEPTANCE_REQUIRED','resumption_condition',jsonb_build_object('kind',k,'policy_sha256',m->>'policy_sha256','cohort_sha256',h,'membership_acceptance_sha256',acc,'independent_specification_not_family_acceptance',true,'intervals_missing',true,'root_family_acceptance_required',true));END IF;
 IF t.stage<>'DERIVE' THEN RAISE EXCEPTION 'POPULATION_STAGE_REQUIRED';END IF;
 IF k='PRACTICAL_INTERVAL_REQUIREMENTS_V2' THEN
  FOR z IN SELECT value i FROM jsonb_array_elements(m->'instruments') LOOP
   v:=jsonb_build_object('policy_sha256',m->>'policy_sha256','cohort_sha256',h,'membership_acceptance_sha256',acc,'company_id',z.i->>'company_id','ticker',z.i->>'ticker','point_evidence',z.i,'supported_point_date','2026-08-03','candidate_session_count',42,'unresolved_known_anchor_session_dates',(SELECT jsonb_agg(session_date ORDER BY session_date) FROM population_top3000_202608_202609_v1.catalog_calendar WHERE session_date<>'2026-08-03'),'full_period_instruments_complete',false,'new_classes_aliases_and_weekend_effective_changes_require_separate_all_class_reconciliation',true,'missing_is_not_absent',true,'calendar_sha256',calendar_hash);
   INSERT INTO population_top3000_202608_202609_v1.ref01_practical_interval_requirement_v1 VALUES(h,acc,z.i->>'company_id',z.i->>'ticker',v,encode(sha256(convert_to(v::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;
   IF FOUND THEN n:=n+1;END IF;
   IF (SELECT content FROM population_top3000_202608_202609_v1.ref01_practical_interval_requirement_v1 WHERE cohort_sha256=h AND acceptance_sha256=acc AND company_id=z.i->>'company_id' AND ticker=z.i->>'ticker') IS DISTINCT FROM v THEN RAISE EXCEPTION 'POPULATION_INTERVAL_REPLAY_CONFLICT';END IF;
  END LOOP;
  SELECT encode(sha256(convert_to(string_agg(record_sha256,E'\n' ORDER BY company_id COLLATE "C",ticker COLLATE "C"),'UTF8')),'hex') INTO out_hash FROM population_top3000_202608_202609_v1.ref01_practical_interval_requirement_v1 WHERE cohort_sha256=h AND acceptance_sha256=acc;
  nextid:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF01','DERIVE','practical-family-specs-v2:'||h||':'||acc,jsonb_build_object('kind','PRACTICAL_FAMILY_SPECS_V2'),t.input_versions,tid);
 ELSIF k='PRACTICAL_FAMILY_SPECS_V2' THEN
  IF (SELECT count(*) FROM population_top3000_202608_202609_v1.ref01_practical_interval_requirement_v1 WHERE cohort_sha256=h AND acceptance_sha256=acc)<>3000 THEN RAISE EXCEPTION 'POPULATION_INTERVAL_REQUIREMENTS_MISSING';END IF;
  IF (SELECT count(*) FROM population_top3000_202608_202609_v1.catalog_family_contract)<>24 OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.catalog_family_contract WHERE NOT rules ? family_id) THEN RAISE EXCEPTION 'POPULATION_FAMILY_CONTRACT_CHANGED';END IF;
  FOR z IN SELECT * FROM population_top3000_202608_202609_v1.catalog_family_contract ORDER BY family_id LOOP
   v:=jsonb_build_object('family_id',z.family_id,'policy_sha256',m->>'policy_sha256','cohort_sha256',h,'membership_acceptance_sha256',acc,'company_manifest_sha256',m->>'company_sha256','original_contract_sha256',z.contract_sha256,'expected_population_predicate',rules->>z.family_id,'selected_company_count',3000,'calendar_sha256',calendar_hash,'expected_observation_count',NULL,'population_state','SPECIFIED_NOT_ENUMERATED','family_accepted',false,'new_policy_supersedes_exact_global_rank_only',true,'missing_is_not_absent',true,'shared_not_multiplied_by_companies',z.family_id IN('CTX07','CTX14','REF03'));
   INSERT INTO population_top3000_202608_202609_v1.ref01_practical_family_spec_v1 VALUES(h,acc,z.family_id,v,encode(sha256(convert_to(v::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;
   IF FOUND THEN n:=n+1;END IF;
   IF (SELECT content FROM population_top3000_202608_202609_v1.ref01_practical_family_spec_v1 WHERE cohort_sha256=h AND acceptance_sha256=acc AND family_id=z.family_id) IS DISTINCT FROM v THEN RAISE EXCEPTION 'POPULATION_FAMILY_REPLAY_CONFLICT';END IF;
  END LOOP;
  SELECT encode(sha256(convert_to(string_agg(record_sha256,E'\n' ORDER BY family_id COLLATE "C"),'UTF8')),'hex') INTO out_hash FROM population_top3000_202608_202609_v1.ref01_practical_family_spec_v1 WHERE cohort_sha256=h AND acceptance_sha256=acc;
  nextid:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF01','DERIVE','practical-filing-expectations-v2:'||h||':'||acc,jsonb_build_object('kind','PRACTICAL_FILING_EXPECTATIONS_V2'),t.input_versions,tid);
 ELSE
  IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.sec_source_manifest_v1 WHERE source_id='SEC_Q3_2026_MASTER_INDEX' AND raw_state='COMPLETE_VERIFIED' AND expected_parts=152 AND source_sha256='24f0ee423c27ffe0d2e04ad989ba45e4a0613bad88f805f145b554a5b3e81a62') THEN RAISE EXCEPTION 'POPULATION_SEC_SOURCE_CHANGED';END IF;
  WITH chosen AS MATERIALIZED(SELECT value->>'company_id' company_id FROM jsonb_array_elements(m->'companies')),
  rows AS(SELECT i.*,c.company_id FROM population_top3000_202608_202609_v1.sec_filing_index_v1 i JOIN chosen c ON c.company_id='CIK:'||lpad(i.filing_cik,10,'0') WHERE i.source_id='SEC_Q3_2026_MASTER_INDEX' AND i.filing_date BETWEEN '2026-08-01' AND '2026-09-30'),
  vals AS(SELECT *,jsonb_build_object('policy_sha256',m->>'policy_sha256','cohort_sha256',h,'membership_acceptance_sha256',acc,'source_id',source_id,'source_line_number',source_line_number,'source_sha256','24f0ee423c27ffe0d2e04ad989ba45e4a0613bad88f805f145b554a5b3e81a62','company_id',company_id,'accession_number',accession_number,'form',form,'filing_date',filing_date,'source_filename',source_filename,'expected_unit','SELECTED_COMPANY_INDEX_ASSOCIATION_REQUIRING_ROLE_DOCUMENT_TIME_VERIFICATION','filing_role_verified',false,'accepted_at_verified',false,'documents_exhibits_complete',false,'prewindow_support_complete',false) v FROM rows)
  INSERT INTO population_top3000_202608_202609_v1.ref01_practical_filing_expectation_v1 SELECT h,acc,source_id,source_line_number,company_id,accession_number,vals.v,encode(sha256(convert_to(vals.v::text,'UTF8')),'hex') FROM vals ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS n=ROW_COUNT;
  IF (SELECT count(*) FROM population_top3000_202608_202609_v1.ref01_practical_filing_expectation_v1 WHERE cohort_sha256=h AND acceptance_sha256=acc)<>55265 THEN RAISE EXCEPTION 'POPULATION_REVIEWED_INDEX_ASSOCIATION_COUNT_CHANGED';END IF;
  IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_practical_filing_expectation_v1 e JOIN population_top3000_202608_202609_v1.sec_filing_index_v1 i USING(source_id,source_line_number) WHERE e.cohort_sha256=h AND e.acceptance_sha256=acc AND (e.record_sha256 IS DISTINCT FROM encode(sha256(convert_to(e.content::text,'UTF8')),'hex') OR e.content->>'form' IS DISTINCT FROM i.form OR e.content->>'accession_number' IS DISTINCT FROM i.accession_number OR e.content->>'company_id' IS DISTINCT FROM 'CIK:'||lpad(i.filing_cik,10,'0') OR e.content->>'filing_date' IS DISTINCT FROM i.filing_date::text OR e.content->>'source_filename' IS DISTINCT FROM i.source_filename)) THEN RAISE EXCEPTION 'POPULATION_FILING_REPLAY_CONFLICT';END IF;
  SELECT encode(sha256(convert_to(string_agg(record_sha256,E'\n' ORDER BY source_id COLLATE "C",source_line_number),'UTF8')),'hex') INTO out_hash FROM population_top3000_202608_202609_v1.ref01_practical_filing_expectation_v1 WHERE cohort_sha256=h AND acceptance_sha256=acc;
  IF out_hash IS DISTINCT FROM '90f21c07f4786ba465b22cd90a2716ebdeb04510792a3dec567d67653fff5dc4' THEN RAISE EXCEPTION 'POPULATION_FILING_OUTPUT_CHANGED';END IF;
 END IF;
 RETURN jsonb_build_object('state','COMPLETE','commit_receipt',jsonb_build_object('commit_key',k||':'||h||':'||acc,'output_sha256',out_hash,'new_committed_units',n,'immutable_output_ids',jsonb_build_array(out_hash),'input_versions',t.input_versions,'explicit_successor_task_id',nextid,'engineering_successor_event_ids',t.input_versions->'engineering_successor_event_ids','membership_accepted',true,'family_accepted',false,'full_period_instruments_complete',false,'financial_facts_accepted',false));
END $f$;
