CREATE TEMP TABLE population_integration_result(v jsonb);
DO $integrate$
DECLARE d jsonb;d1 jsonb;d2 jsonb;next1 bigint;next2 bigint;reviewid bigint;runtimeid bigint;integration bigint;iv jsonb;tid uuid;
BEGIN
