CREATE TEMP TABLE population_test_receipt(v jsonb);
DO $test$
DECLARE iv jsonb;tid uuid;aid uuid;token text:='population-v2-rollback-only';r jsonb;f jsonb;firstid uuid;res jsonb:='[]';count_before bigint;
BEGIN
 SELECT jsonb_build_object('scope_sha256','8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd','policy_sha256',s.policy_sha256,'cohort_sha256',s.snapshot_sha256,'source_sha256',s.source_sha256,'membership_acceptance_sha256',m.acceptance_sha256,'family_contract_sha256','e47a1e4152768418bd8e6187310b34cfc7b096edbc1e1de11fe243275e046dc0','filing_index_sha256','5605c4be0784a72b23371b7e5083e0421fcf5ecd3b08d9e416d4a7a434e5c35e','calendar_sha256','cb97feec5b3ac3ae136b1bc7085ed842f2aaca5b6c98f97c0cb1c1dae8f336a1') INTO iv FROM population_top3000_202608_202609_v1.ref01_practical_snapshot_v1 s JOIN population_top3000_202608_202609_v1.ref01_practical_membership_v1 m USING(snapshot_sha256);
 firstid:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF01','DERIVE','practical-interval-requirements-v2:'||(iv->>'cohort_sha256')||':'||(iv->>'membership_acceptance_sha256'),'{"kind":"PRACTICAL_INTERVAL_REQUIREMENTS_V2"}',iv);tid:=firstid;
 FOR iteration IN 1..3 LOOP
  aid:=gen_random_uuid();
  UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='LEASED',attempt_id=aid,lease_until=clock_timestamp()+interval '5 minutes',owner_fence=3,stop_generation=1 WHERE task_id=tid;
  INSERT INTO population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256) SELECT aid,tid,1,encode(sha256(convert_to(token,'UTF8')),'hex'),3,1,function_sha256 FROM population_top3000_202608_202609_v1.pipeline_adapter WHERE family_id='REF01' AND stage='DERIVE';
  IF iteration=1 THEN
   BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions=jsonb_set(input_versions,'{policy_sha256}','"wrong"') WHERE task_id=tid;PERFORM population_top3000_202608_202609_v1.ref01_practical_population_worker_v2(aid,token);RAISE EXCEPTION 'BAD_POLICY_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'POPULATION_FROZEN_INPUT_MISMATCH' THEN RAISE;END IF;END;
   BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions=jsonb_set(input_versions,'{membership_acceptance_sha256}','"wrong"') WHERE task_id=tid;PERFORM population_top3000_202608_202609_v1.ref01_practical_population_worker_v2(aid,token);RAISE EXCEPTION 'BAD_ACCEPTANCE_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'POPULATION_FROZEN_INPUT_MISMATCH' THEN RAISE;END IF;END;
   BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions=jsonb_set(input_versions,'{source_sha256}','"wrong"') WHERE task_id=tid;PERFORM population_top3000_202608_202609_v1.ref01_practical_population_worker_v2(aid,token);RAISE EXCEPTION 'BAD_SOURCE_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'POPULATION_FROZEN_INPUT_MISMATCH' THEN RAISE;END IF;END;
   BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions=jsonb_set(input_versions,'{calendar_sha256}','"wrong"') WHERE task_id=tid;PERFORM population_top3000_202608_202609_v1.ref01_practical_population_worker_v2(aid,token);RAISE EXCEPTION 'BAD_CALENDAR_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'POPULATION_CALENDAR_CHANGED' THEN RAISE;END IF;END;
   BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET stopped=true WHERE singleton;PERFORM population_top3000_202608_202609_v1.ref01_practical_population_worker_v2(aid,token);RAISE EXCEPTION 'BAD_STOP_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM='BAD_STOP_ACCEPTED' THEN RAISE;END IF;END;
   BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET owner_fence=4 WHERE singleton;PERFORM population_top3000_202608_202609_v1.ref01_practical_population_worker_v2(aid,token);RAISE EXCEPTION 'BAD_OWNER_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM='BAD_OWNER_ACCEPTED' THEN RAISE;END IF;END;
   BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET admitted_until=clock_timestamp()-interval '1 second' WHERE singleton;PERFORM population_top3000_202608_202609_v1.ref01_practical_population_worker_v2(aid,token);RAISE EXCEPTION 'BAD_EXPIRY_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM='BAD_EXPIRY_ACCEPTED' THEN RAISE;END IF;END;
  END IF;
  IF iteration=3 THEN
   BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions=jsonb_set(input_versions,'{filing_index_sha256}','"wrong"') WHERE task_id=tid;PERFORM population_top3000_202608_202609_v1.ref01_practical_population_worker_v2(aid,token);RAISE EXCEPTION 'BAD_INDEX_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'POPULATION_FILING_INDEX_CHANGED' THEN RAISE;END IF;END;
  END IF;
  r:=population_top3000_202608_202609_v1.ref01_adjudication_route_v3(aid,token,'DERIVE');
  IF (r#>>'{commit_receipt,new_committed_units}')::int<>(CASE iteration WHEN 1 THEN 3000 WHEN 2 THEN 24 ELSE 55265 END) THEN RAISE EXCEPTION 'WRONG_COMMIT_COUNT';END IF;
  IF (population_top3000_202608_202609_v1.ref01_practical_population_worker_v2(aid,token)#>>'{commit_receipt,new_committed_units}')::int<>0 THEN RAISE EXCEPTION 'REPLAY_DUPLICATES';END IF;
  IF iteration=3 THEN
   BEGIN UPDATE population_top3000_202608_202609_v1.ref01_practical_filing_expectation_v1 SET content=jsonb_set(content,'{form}','"SYNTHETIC_TAMPER"') WHERE source_line_number=(SELECT min(source_line_number) FROM population_top3000_202608_202609_v1.ref01_practical_filing_expectation_v1);
   PERFORM population_top3000_202608_202609_v1.ref01_practical_population_worker_v2(aid,token);RAISE EXCEPTION 'CONFLICT_REPLAY_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'POPULATION_FILING_REPLAY_CONFLICT' THEN RAISE;END IF;END;
  END IF;
  IF iteration=3 THEN
   BEGIN UPDATE population_top3000_202608_202609_v1.ref01_practical_filing_expectation_v1 SET content=jsonb_set(content,'{accepted_at_verified}','true'),record_sha256=encode(sha256(convert_to(jsonb_set(content,'{accepted_at_verified}','true')::text,'UTF8')),'hex') WHERE source_line_number=(SELECT min(source_line_number) FROM population_top3000_202608_202609_v1.ref01_practical_filing_expectation_v1);
   PERFORM population_top3000_202608_202609_v1.ref01_practical_population_worker_v2(aid,token);RAISE EXCEPTION 'REHASHED_TAMPER_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'POPULATION_FILING_OUTPUT_CHANGED' THEN RAISE;END IF;END;
  END IF;
  f:=population_top3000_202608_202609_v1.pipeline_finish_v1(aid,token,r);
  IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_commit WHERE task_id=tid AND new_committed_units>0) THEN RAISE EXCEPTION 'NO_ACTUAL_COMMIT';END IF;
  res:=res||jsonb_build_array(jsonb_build_object('kind',(SELECT payload->>'kind' FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid),'output_sha256',r#>>'{commit_receipt,output_sha256}','units',r#>>'{commit_receipt,new_committed_units}'));
  tid:=(r#>>'{commit_receipt,explicit_successor_task_id}')::uuid;
 END LOOP;
 IF (SELECT sum(jsonb_array_length(content->'unresolved_known_anchor_session_dates')) FROM population_top3000_202608_202609_v1.ref01_practical_interval_requirement_v1)<>123000 THEN RAISE EXCEPTION 'UNKNOWN_SESSION_COUNT';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_practical_family_spec_v1 WHERE content->>'expected_observation_count' IS NOT NULL OR content->>'family_accepted'<>'false') THEN RAISE EXCEPTION 'FALSE_FAMILY_ACCEPTANCE';END IF;
 INSERT INTO population_test_receipt VALUES(jsonb_build_object('result','PASS','rehashed_boolean_tamper_rejected',true,'three_actual_commit_chains',res,'unknown_known_anchor_session_checks',123000,'full_instrument_population_complete',false,'family_acceptance',false,'wrong_policy_source_acceptance_calendar_owner_stop_expiry_rejected',true,'no_provider_calls',true,'all_test_mutations_rolled_back',true));
END $test$;
SELECT v FROM population_test_receipt;
ROLLBACK;

